for name,count in [('core.log',656),('all-api.log',371),('shared.log',7),('focused.log',1)]:assert f'{count} passed; 0 failed' in (base/name).read_text(),name
assert 'pass=43 skip=0 fail=0 timeout=0 crash=0 unclassified=0 total=43' in (base/'framework.log').read_text()
source=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();assert source==(bundle/'source-commit.txt').read_text().strip();assert not subprocess.check_output(['git','diff','--','crates'],text=True)
for path in [base/'core656-source-sha256.json',bundle/'source-sha256.json']:
 m=json.loads(path.read_text());assert all(hashlib.sha256(Path(n).read_bytes()).hexdigest()==h for n,h in m.items())
for n in ['shadow.diff','buffer-oracle.diff','buffer-concat-oracle.diff','buffer-latin1-oracle.diff','buffer-poison-oracle.diff']:assert not(base/n).read_bytes(),n
